cases.script:
H=/opt/bashos-parity/harness/helpers/mig-w3-claude-mock.py
nap() { read -t "$1" -u 7 7<>"$HOME/nap.fifo"; }
serve() { /usr/bin/python3 "$H" serve "$2" "$HOME/pki/$3.pem" "$HOME/pki/$3.key" "$PWD/$1.script" "$HOME/$1.jsonl" 25 & srv=$!
  local i; for ((i = 0; i < 200; i++)); do [ -e "$HOME/$1.jsonl.ready" ] && break; nap 0.05; done; }
stopsrv() { kill "$srv" 2>/dev/null; wait "$srv" 2>/dev/null; }
key=$(<"$HOME/key.txt")
export ANTHROPIC_API_KEY=$key BASHCLAUDE_HOST=127.0.0.1 BASHCLAUDE_CA="$HOME/pki/ca.pem"
export BASHCLAUDE_MAX_RETRIES=0
report() { local out; out=$(<"$HOME/out.txt"); local d=no z=no; [[ $(<"$HOME/err.txt") == *"TLS handshake failed"* ]] && d=yes; [ "$2" = 0 ] && z=yes; echo "$1 rc-zero=$z stdout=[$out] handshake-diag=$d"; }
run() { export BASHCLAUDE_PORT=$2; serve "$1" "$2" "$3"; BASHCLAUDE_CA="$HOME/pki/$4.pem" claude prompt $5 hi > "$HOME/out.txt" 2> "$HOME/err.txt"; local rc=$?; stopsrv; report "$1" "$rc"; }
run tlsa 20711 server ca ""
run tlsb 20712 rogue ca ""
run tlsc 20713 wrong ca ""
run tlsd 20714 rogue ca "-k"
